// Normalize incoming signup payload
const raw = $input.first().json;
const body = raw.body || raw;
const user = body.user || body;

const id = user.id || `usr-${Date.now()}`;
const name = (user.name || 'Healthcare Colleague').trim();
const email = (user.email || '').trim().toLowerCase();
const role = (user.role || 'candidate').toLowerCase();
const specialty = (user.specialty || 'General Healthcare').trim();
const clinicalLicenseNumber = (user.clinicalLicenseNumber || '').trim();
const organization = (user.organization || 'Independent Provider').trim();

const isCandidate = role === 'candidate';
const roleLabel = isCandidate ? 'Healthcare Clinician / Candidate' : 'Healthcare Facility / Employer';

const welcomeTitle = isCandidate
  ? `Welcome to PulseCareers, ${name}! Your clinical profile is ready.`
  : `Welcome to PulseCareers, ${organization}! Your employer hiring dashboard is active.`;

return [{
  json: {
    id,
    name,
    email,
    role,
    roleLabel,
    specialty,
    clinicalLicenseNumber: clinicalLicenseNumber || 'N/A',
    organization,
    isCandidate,
    welcomeTitle,
    registeredAt: new Date().toISOString()
  }
}];

